from jsonb_to_recordset($q$[{"position":1,"type":"multi","text":"In Bayes' Theorem, how is the conditional probability of event A, given that event B has already occurred, formally denoted?","options":["P(A)","P(A|B)","P(B)","P(B|A)"],"answer":[1],"weight":1,"extra":{}},{"position":2,"type":"multi","text":"Which formula is used to compute the Expected Value for categorical variables?","options":["E(x) = nx","E(n) = n × p","E(x) = n × q","E(x) = n × p"],"answer":[3],"weight":1,"extra":{}},{"position":3,"type":"text","text":"In a game where two six-sided dice are rolled, what is the expected value of the sum of the results?","options":null,"answer":"7","weight":1,"extra":{}},{"position":4,"type":"radio","text":"The linearity of expectation states that the expected value of the sum of random variables is equal to the sum of their individual expected values, but this rule only applies if the variables are independent.","options":["True","False"],"answer":[1],"weight":1,"extra":{}},{"position":5,"type":"multi","text":"Based on the Bayes' Theorem application for a standard deck of 52 cards, what is the posterior probability that a randomly drawn card is a King, given that it is a Face card?","options":["75%","1/3","1/4","1/2","33.33%","0.25"],"answer":[1,4],"weight":1,"extra":{}}]$q$::jsonb) as x(position int,type text,text text,options jsonb,answer jsonb,weight int,extra jsonb);

