 on conflict (slug) do update set title=excluded.title, meta=excluded.meta returning id),
 d as (delete from questions where quiz_id=(select id from q))
insert into questions(quiz_id,position,type,text,options,answer,weight,extra)
select (select id from q),x.position,x.type,x.text,x.options,x.answer,x.weight,x.extra
